/*
 * Workspace slugs and the paths built from them. No Next.js or request imports, so scripts such as
 * `npm run demo:seed` print the same links the app routes to; `access.ts` adds the request checks.
 */

export const WORKSPACE_SECTIONS = [
  "timeline",
  "dashboard",
  "connections",
  "alerts",
  "projects",
  "settings",
] as const;

export type WorkspaceSection = (typeof WORKSPACE_SECTIONS)[number];

// Slugs are generated by the database (random lowercase base32), never typed by people, so
// anything else is rejected before it reaches a query or a redirect target.
const SLUG_PATTERN = /^[a-z0-9]{1,64}$/;

export function isWorkspaceSlug(slug: string): boolean {
  return SLUG_PATTERN.test(slug);
}

/** Path to a section of a workspace. Only call with a slug that passed `isWorkspaceSlug`. */
export function workspacePath(slug: string, section: WorkspaceSection): string {
  return `/w/${slug}/${section}`;
}

/**
 * Where a workspace opens: `/app`, `/w/<slug>`, the switcher, and the return after sign-in all
 * land here. The timeline, because it is the live pulse of the project (deploys, payments,
 * alerts as they happen); the dashboard's totals are one click away (#135).
 */
export function workspaceHome(slug: string): string {
  return workspacePath(slug, "timeline");
}
